local names = {
  "cwd", "config_file", "config_dir", "config_name", "dashboard_title",
  "db_type", "db_host", "db_port", "db_name", "db_user", "db_url",
  "panel_index", "panel_title", "chart_type", "interval", "max_rows",
  "timeout", "refresh_count", "now", "today", "hostname", "user", "os",
  "nvim_version", "arch",
}
local rows = {}
for _, n in ipairs(names) do
  rows[#rows + 1] = { n, tostring(meta[n]) }
end
-- Run records: this run, its life, the previous refreshes.
rows[#rows + 1] = { "run.kind / run.depth", meta.run.kind .. " / " .. meta.run.depth }
rows[#rows + 1] = { "#runs", tostring(#meta.runs) }
rows[#rows + 1] = { "prev.ok", tostring(meta.prev and meta.prev.ok) }
rows[#rows + 1] = { "prev_ok.id", tostring(meta.prev_ok and meta.prev_ok.id) }
rows[#rows + 1] = { "#prev_runs / #prev_ok_runs", ("%d / %d"):format(meta.prev_runs and #meta.prev_runs or 0, meta.prev_ok_runs and #meta.prev_ok_runs or 0) }
return { columns = { "meta", "value" }, rows = rows }
